CREATE VIEW v_observation_latest_per_code AS SELECT patient_id, code, any_value(code_display) AS code_display, count_star() AS readings, arg_max(value_quantity_value, effective_datetime) AS latest_value, arg_max(value_quantity_unit, effective_datetime) AS unit, max(effective_datetime) AS latest_at, min(effective_datetime) AS first_at FROM observation GROUP BY patient_id, code;;

CREATE VIEW v_record_mix AS SELECT patient_id, source_types AS resource_type, row_count, (source_types IN ('Claim', 'ExplanationOfBenefit')) AS is_billing FROM ((SELECT patient_id, 'Claim' AS source_types, count_star() AS row_count FROM claim GROUP BY patient_id) UNION ALL (((((SELECT patient_id, 'ExplanationOfBenefit', count_star() FROM explanation_of_benefit GROUP BY patient_id) UNION ALL (SELECT patient_id, 'Observation', count_star() FROM observation GROUP BY patient_id)) UNION ALL ((SELECT patient_id, 'Encounter', count_star() FROM encounter GROUP BY patient_id) UNION ALL (SELECT patient_id, 'Procedure', count_star() FROM "procedure" GROUP BY patient_id))) UNION ALL (((SELECT patient_id, 'DiagnosticReport', count_star() FROM diagnostic_report GROUP BY patient_id) UNION ALL (SELECT patient_id, 'Immunization', count_star() FROM immunization GROUP BY patient_id)) UNION ALL ((SELECT patient_id, 'Condition', count_star() FROM condition GROUP BY patient_id) UNION ALL (SELECT patient_id, 'MedicationRequest', count_star() FROM medication_request GROUP BY patient_id)))) UNION ALL (SELECT patient_id, 'AllergyIntolerance', count_star() FROM allergy_intolerance GROUP BY patient_id)));;

